function setupForm(){const form=document.querySelector('form'),boxes=[...form.querySelectorAll('[name=services]')];let draft={};try{draft=JSON.parse(localStorage.getItem('bluechip-inquiry')||'{}')}catch{}for(const el of form.elements)if(el.name&&el.name!=='services'&&draft[el.name])el.value=draft[el.name];boxes.forEach(b=>b.checked=(draft.services||[]).includes(b.value));const pre=new URLSearchParams(location.search).get('service');if(boxes.some(b=>b.value===pre))boxes.forEach(b=>b.checked=b.value===pre);const data=()=>{const f=new FormData(form);return {...Object.fromEntries(f),services:f.getAll('services')}};const save=()=>{try{localStorage.setItem('bluechip-inquiry',JSON.stringify(data()))}catch{document.querySelector('#draft-status').textContent='Storage unavailable. Keep this page open to retain your draft.'}};form.addEventListener('input',save);boxes.forEach(b=>b.addEventListener('change',()=>{if(b.checked)boxes.forEach(o=>{if(o!==b&&(['launch','unsure'].includes(b.value)||['launch','unsure'].includes(o.value)))o.checked=false});document.querySelector('#service-error').textContent='';save()}));document.querySelector('#clear-draft').onclick=()=>{try{localStorage.removeItem('bluechip-inquiry')}catch{}form.reset();document.querySelector('#draft-status').textContent='Saved draft cleared.'};form.onsubmit=e=>{e.preventDefault();if(!boxes.some(b=>b.checked)){document.querySelector('#service-error').textContent='Choose a service or “Not sure yet”.';boxes[0].focus();return}save();const d=data(),body=`Name: ${d.name}\nBusiness: ${d.company}\nEmail: ${d.email}\nPhone: ${d.phone||'Not provided'}\nServices: ${d.services.join(', ')}\nBudget: ${d.budget||'Not specified'}\nTimeline: ${d.timeline||'Flexible'}\n\n${d.message}`;form.replaceChildren();const h=document.createElement('h2');h.textContent='Your inquiry is ready.';h.tabIndex=-1;const p=document.createElement('p');p.textContent='Nothing has been sent yet. Open your email app, review the message, and send it to Bluechip.';const a=document.createElement('a');a.className='button';a.textContent='Open email draft >';a.href='mailto:info@bluechipbranding.net?subject='+encodeURIComponent('Project inquiry: '+d.company)+'&body='+encodeURIComponent(body);form.append(h,p,a);h.focus()}}
const toggle=document.querySelector('#services-toggle'),drop=document.querySelector('.dropdown');const servicesNav=document.querySelector('.nav-services');const setServices=open=>{drop.hidden=!open;toggle.setAttribute('aria-expanded',String(open))};servicesNav.addEventListener('mouseenter',()=>setServices(true));servicesNav.addEventListener('mouseleave',()=>{if(!servicesNav.contains(document.activeElement))setServices(false)});servicesNav.addEventListener('focusin',()=>setServices(true));servicesNav.addEventListener('focusout',e=>{if(!servicesNav.contains(e.relatedTarget))setServices(false)});toggle.onclick=()=>{drop.hidden=!drop.hidden;toggle.setAttribute('aria-expanded',String(!drop.hidden))};document.addEventListener('click',e=>{if(!e.target.closest('.nav-services')){drop.hidden=true;toggle.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){drop.hidden=true;toggle.setAttribute('aria-expanded','false')}});const dialog=document.querySelector('dialog'),menu=document.querySelector('#menu');menu.onclick=()=>{dialog.showModal();menu.setAttribute('aria-expanded','true')};document.querySelector('#close-menu').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{menu.setAttribute('aria-expanded','false');menu.focus()});if(path!=='/')document.title=(main.querySelector('h1')?.textContent||'Page')+' | Bluechip';

// Natty–Niko header interaction, adapted to the static Bluechip navigation.
{
 const header=document.querySelector('.natty-header');
 const mobileDialog=document.querySelector('#mobile-menu');
 const trigger=document.querySelector('#menu');
 const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
 let expanded=false,frame=0,closeTimer;
 function syncHeader(){frame=0;const next=expanded?scrollY>8:scrollY>32;expanded=next;header.dataset.expanded=String(next)}
 addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(syncHeader)},{passive:true});syncHeader();
 function wireSelector(container,items){
  const active=items.findIndex(item=>{const a=item.matches('a')?item:item.querySelector('a');return a&&location.pathname.startsWith(a.getAttribute('href'))});
  function select(index){container.dataset.preview=String(index>=0);container.style.setProperty('--nav-index',Math.max(0,index));items.forEach((item,i)=>item.dataset.preview=String(i===index))}
  items.forEach((item,i)=>{item.addEventListener('pointerenter',()=>select(i));item.addEventListener('focusin',()=>select(i));const a=item.matches('a')?item:item.querySelector('a');if(i===active)a.setAttribute('aria-current','page')});
  container.addEventListener('pointerleave',()=>select(active));container.addEventListener('focusout',e=>{if(!container.contains(e.relatedTarget))select(active)});select(active);
 }
 wireSelector(header.querySelector('nav'),[...header.querySelector('nav').children].filter(e=>e.matches('a,.nav-services')));
 wireSelector(mobileDialog.querySelector('.mobile-island-links'),[...mobileDialog.querySelectorAll('a')]);
 function closeIsland(){if(!mobileDialog.open||mobileDialog.dataset.closing==='true')return;mobileDialog.dataset.expanded=String(expanded);mobileDialog.dataset.closing='true';trigger.setAttribute('aria-expanded','false');const duration=reduceMotion.matches?0:expanded?420:480;closeTimer=setTimeout(()=>{mobileDialog.close();delete mobileDialog.dataset.closing;trigger.focus({preventScroll:true})},duration)}
 trigger.onclick=()=>{if(mobileDialog.open){closeIsland();return}clearTimeout(closeTimer);delete mobileDialog.dataset.closing;mobileDialog.dataset.expanded=String(expanded);mobileDialog.showModal();trigger.setAttribute('aria-expanded','true')};
 document.querySelector('#close-menu').onclick=closeIsland;
 mobileDialog.addEventListener('cancel',e=>{e.preventDefault();closeIsland()});
 mobileDialog.addEventListener('click',e=>{if(e.target===mobileDialog){const r=mobileDialog.getBoundingClientRect();if(e.clientY>r.bottom||e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)closeIsland()}});
 const desktopQuery=matchMedia('(min-width:1024px)');desktopQuery.addEventListener('change',e=>{if(e.matches&&mobileDialog.open){clearTimeout(closeTimer);mobileDialog.close();delete mobileDialog.dataset.closing;trigger.setAttribute('aria-expanded','false')}});
}
